import (
	context "context"
	fern "github.com/go-required-nullable-round-trip/fern"
	fernclient "github.com/go-required-nullable-round-trip/fern/client"
)

client := fernclient.NewClient()
response, err := client.GetAccounts(
	context.TODO(),
	&fern.GetAccountsRequest{
		AccessToken: "access_token",
		AccountIDs: []string{
			"account_ids",
			"account_ids",
		},
	},
)
